create function public.business_profile_valid(d jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text; h jsonb; l jsonb;
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>8 or not d ?& array['name','description','email','phone','website','areas','hours','logo'] then return false; end if;
 foreach k in array array['name','description','email','phone','website','areas'] loop
  if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false; end if;
 end loop;
 if char_length(d->>'name') not between 2 and 120 or char_length(d->>'description')>2000 or char_length(d->>'email')>254 or char_length(d->>'phone')>40 or char_length(d->>'website')>500 or char_length(d->>'areas')>1000 then return false;end if;
 if (d->>'email'<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (d->>'phone'<>'' and d->>'phone' !~ '^[+0-9 ()-]{5,40}$') or (d->>'website'<>'' and d->>'website' !~ '^https://[^/@[:space:]]+([/:?#][^[:space:]]*)?$') then return false; end if;
 if jsonb_typeof(d->'hours') is distinct from 'array' or jsonb_array_length(d->'hours')<>7 then return false;end if;
 for h in select value from jsonb_array_elements(d->'hours') loop
  if h='null'::jsonb then continue;end if;
  if jsonb_typeof(h) is distinct from 'array' or jsonb_array_length(h)<>2 then return false;end if;
  if jsonb_typeof(h->0) is distinct from 'string' or jsonb_typeof(h->1) is distinct from 'string' or h->>0 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>1 !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or h->>0>=h->>1 then return false;end if;
 end loop;
 l=d->'logo';if l<>'null'::jsonb then
  if jsonb_typeof(l) is distinct from 'object' or (select count(*) from jsonb_object_keys(l))<>2 or not l ?& array['mime','data'] or jsonb_typeof(l->'mime') is distinct from 'string' or jsonb_typeof(l->'data') is distinct from 'string' or l->>'mime' not in ('image/png','image/jpeg','image/webp') or char_length(l->>'data')>200000 or l->>'data' !~ '^[A-Za-z0-9+/]+={0,2}$' then return false;end if;
 end if;
 return true;
exception when others then return false;
end $$

create policy profile_owner on public.business_profiles for all to authenticated
 using(exists(select 1 from public.businesses b where b.id=business_id))
 with check(exists(select 1 from public.businesses b where b.id=business_id))

create function public.business_profile_save(p_business uuid,p_environment text,p_slug text,p_draft jsonb,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare n integer;
begin
 if not exists(select 1 from public.businesses where id=p_business) then raise exception 'Profile permission denied';end if;
 if p_version=0 then insert into public.business_profiles(business_id,environment,slug,draft) values(p_business,p_environment,p_slug,p_draft);
 else update public.business_profiles set slug=p_slug,draft=p_draft,version=version+1 where business_id=p_business and environment=p_environment and version=p_version;get diagnostics n=row_count;if n<>1 then raise exception 'Draft changed. Reload before saving or publishing.';end if;end if;
 return '{}'::jsonb;
end $$

create function public.business_profile_publish(p_business uuid,p_environment text,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.business_profiles; zone text;
begin
 select * into r from public.business_profiles where business_id=p_business and environment=p_environment for update;
 if not found or r.version<>p_version then raise exception 'Draft changed. Reload before saving or publishing.';end if;
 if btrim(r.draft->>'description')='' or btrim(r.draft->>'areas')='' or ((r.draft->>'email')='' and (r.draft->>'phone')='' and (r.draft->>'website')='') then raise exception 'Add a description, service areas and at least one public contact before publishing.';end if;
 select time_zone into zone from public.businesses where id=p_business;
 if zone is null then raise exception 'Complete business country and time zone first.';end if;
 insert into public.business_public_pages(business_id,environment,slug,document,time_zone) values(p_business,p_environment,r.slug,r.draft,zone)
 on conflict(business_id,environment) do update set slug=excluded.slug,document=excluded.document,time_zone=excluded.time_zone;
 update public.business_profiles set published_at=now(),published_slug=r.slug where business_id=p_business and environment=p_environment;
 return '{}'::jsonb;
end $$

create function public.business_profile_unpublish(p_business uuid,p_environment text) returns jsonb language plpgsql security invoker set search_path='' as $$
begin
 if not exists(select 1 from public.business_profiles where business_id=p_business and environment=p_environment) then raise exception 'Profile permission denied';end if;
 delete from public.business_public_pages where business_id=p_business and environment=p_environment;
 update public.business_profiles set published_at=null,published_slug=null where business_id=p_business and environment=p_environment;
 return '{}'::jsonb;
end $$

create function public.business_services_valid(d jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare s jsonb; k text; ids text[]='{}';
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>2 or not d ?& array['currency','items'] or jsonb_typeof(d->'currency') is distinct from 'string' or d->>'currency' not in ('ZAR','USD','GBP','EUR','AUD','CAD','NZD','BWP','NAD','ZMW','KES','NGN','GHS','MUR','SZL','LSL','MZN','UGX','TZS','RWF','JPY','INR','AED','CHF') or jsonb_typeof(d->'items') is distinct from 'array' or jsonb_array_length(d->'items')>100 then return false;end if;
 for s in select value from jsonb_array_elements(d->'items') loop
  if jsonb_typeof(s) is distinct from 'object' or (select count(*) from jsonb_object_keys(s))<>8 or not s ?& array['id','name','description','duration','mode','amount','visible','archived'] then return false;end if;
  foreach k in array array['id','name','description','mode'] loop
   if jsonb_typeof(s->k) is distinct from 'string' or s->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;
  end loop;
  if s->>'id' !~ '^[a-f0-9]{32}$' or s->>'id'=any(ids) or char_length(btrim(s->>'name')) not between 2 and 120 or char_length(s->>'description')>2000 or s->>'mode' not in ('fixed','from','quote') or jsonb_typeof(s->'duration') is distinct from 'number' or s->>'duration' !~ '^[0-9]+$' or (s->>'duration')::integer not between 1 and 10080 or jsonb_typeof(s->'visible') is distinct from 'boolean' or jsonb_typeof(s->'archived') is distinct from 'boolean' then return false;end if;
  ids=array_append(ids,s->>'id');
  if s->>'mode'='quote' then if s->'amount'<>'null'::jsonb then return false;end if;
  elsif jsonb_typeof(s->'amount') is distinct from 'number' or s->>'amount' !~ '^[0-9]+$' or (s->>'amount')::bigint not between 0 and 999999999 then return false;end if;
  if d->>'currency' in ('JPY','UGX','RWF') and s->>'mode'<>'quote' and (s->>'amount')::bigint%100<>0 then return false;end if;
 end loop;return true;
exception when others then return false;
end $$

create policy services_owner on public.business_service_catalogues for all to authenticated
 using(exists(select 1 from public.businesses b where b.id=business_id))
 with check(exists(select 1 from public.businesses b where b.id=business_id))

create function public.business_services_save(p_business uuid,p_environment text,p_draft jsonb,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare n integer;
begin
 if not exists(select 1 from public.businesses where id=p_business) then raise exception 'Services permission denied';end if;
 if p_version=0 then insert into public.business_service_catalogues(business_id,environment,draft) values(p_business,p_environment,p_draft);
 else update public.business_service_catalogues set draft=p_draft,version=version+1 where business_id=p_business and environment=p_environment and version=p_version;get diagnostics n=row_count;if n<>1 then raise exception 'Services changed. Reload before saving or publishing.';end if;end if;
 return '{}'::jsonb;
end $$

create function public.business_services_publish(p_business uuid,p_environment text,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.business_service_catalogues; snap jsonb;
begin
 -- Match profile publishing lock order to serialize snapshot changes and avoid lost updates.
 perform 1 from public.business_profiles where business_id=p_business and environment=p_environment for update;
 select * into r from public.business_service_catalogues where business_id=p_business and environment=p_environment for update;
 if not found or r.version<>p_version then raise exception 'Services changed. Reload before saving or publishing.';end if;
 select jsonb_build_object('currency',r.draft->>'currency','items',coalesce(jsonb_agg(value) filter(where (value->>'visible')::boolean and not (value->>'archived')::boolean),'[]'::jsonb)) into snap from jsonb_array_elements(r.draft->'items');
 update public.business_service_catalogues set published=snap,published_version=version where business_id=p_business and environment=p_environment;
 update public.business_public_pages set services=snap where business_id=p_business and environment=p_environment;
 return '{}'::jsonb;
end $$

create function public.business_page_services_snapshot() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 select published into new.services from public.business_service_catalogues where business_id=new.business_id and environment=new.environment;
 new.services=coalesce(new.services,'{"currency":"ZAR","items":[]}'::jsonb);return new;
end $$

create function enquiry_private.submit(p_environment text,p_slug text,p_service text,p_name text,p_email text,p_phone text,p_requirements text,p_request uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare page public.business_public_pages; previous public.business_enquiries; service text=''; k text; n integer;
begin
 if p_environment is null or p_slug is null or p_service is null or p_name is null or p_email is null or p_phone is null or p_requirements is null or p_request is null then raise exception 'Check enquiry details';end if;
 if not exists(select 1 from enquiry_private.ingress where environment=p_environment and enabled) then raise exception 'Enquiries unavailable';end if;
 if char_length(p_slug) not between 3 and 64 or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or char_length(p_service)>32 or p_name<>btrim(p_name) or char_length(p_name) not between 2 and 120 or char_length(p_email)>254 or char_length(p_phone)>40 or char_length(p_requirements) not between 10 and 4000 or p_requirements<>btrim(p_requirements) or (p_email='' and p_phone='') or (p_email<>'' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (p_phone<>'' and (p_phone !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(p_phone,'[^0-9]','','g'))<5)) or p_name||p_email||p_phone ~ '[[:cntrl:]]' or p_requirements ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then raise exception 'Check enquiry details';end if;
 -- Lock publication until commit so unpublish cannot race validation and intake.
 select * into page from public.business_public_pages where environment=p_environment and slug=p_slug for share;
 if not found then raise exception 'Page unavailable';end if;
 if p_service<>'' then
  select s->>'name' into service from jsonb_array_elements(page.services->'items') s where s->>'id'=p_service and s->>'visible'='true' and s->>'archived'='false';
  if service is null then raise exception 'Service unavailable';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request::text,0));
 select * into previous from public.business_enquiries where request_id=p_request;
 if found then
  if previous.business_id=page.business_id and previous.environment=p_environment and previous.service_id=p_service and previous.customer_name=p_name and previous.email=p_email and previous.phone=p_phone and previous.requirements=p_requirements then return '{}'::jsonb;end if;
  raise exception 'Request already used';
 end if;
 -- Database limits also protect callers bypassing the PHP form: 30/page/hour, 5/contact/hour.
 foreach k in array array['page:'||p_environment||':'||page.business_id::text,'contact:'||p_environment||':'||encode(extensions.digest(lower(coalesce(nullif(p_email,''),regexp_replace(p_phone,'[^0-9]','','g'))),'sha256'),'hex')] loop
  insert into enquiry_private.rate_limits as r values(k,date_trunc('hour',now()),1) on conflict(key) do update set window_start=excluded.window_start,attempts=case when r.window_start=excluded.window_start then r.attempts+1 else 1 end returning attempts into n;
  if n>(case when k like 'page:%' then 30 else 5 end) then raise exception 'Too many enquiries. Please try again later.';end if;
 end loop;
 delete from enquiry_private.rate_limits where window_start<now()-interval '2 hours';
 insert into public.business_enquiries(business_id,environment,request_id,page_slug,service_id,service_name,customer_name,email,phone,requirements) values(page.business_id,p_environment,p_request,p_slug,p_service,service,p_name,p_email,p_phone,p_requirements);
 return '{}'::jsonb;
end$$

create function public.business_enquiry_status(p_business uuid,p_environment text,p_id uuid,p_status text,p_version integer) returns jsonb language plpgsql security invoker set search_path='' as $$
declare n integer;
begin
 update public.business_enquiries set status=p_status where id=p_id and business_id=p_business and environment=p_environment and version=p_version;
 get diagnostics n=row_count;if n<>1 then raise exception 'Enquiry changed or unavailable. Reload before updating.';end if;
 return '{}'::jsonb;
end$$

create function quote_private.valid(d jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare s jsonb;k text;t bigint=0;
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>6 or not d ?& array['name','email','phone','notes','currency','items'] then return false;end if;
 foreach k in array array['name','email','phone','notes','currency'] loop
 if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;end loop;
 if char_length(btrim(d->>'name')) not between 2 and 120 or char_length(d->>'email')>254 or char_length(d->>'phone')>40 or char_length(d->>'notes')>2000 or (d->>'email'='' and d->>'phone'='') or (d->>'email'<>'' and d->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (d->>'phone'<>'' and (d->>'phone' !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(d->>'phone','[^0-9]','','g'))<5)) or d->>'currency' not in ('ZAR','USD','GBP','EUR','AUD','CAD','NZD','BWP','NAD','ZMW','KES','NGN','GHS','MUR','SZL','LSL','MZN','UGX','TZS','RWF','JPY','INR','AED','CHF') or jsonb_typeof(d->'items') is distinct from 'array' or jsonb_array_length(d->'items') not between 1 and 20 then return false;end if;
 for s in select value from jsonb_array_elements(d->'items') loop
 if jsonb_typeof(s) is distinct from 'object' or (select count(*) from jsonb_object_keys(s))<>3 or not s ?& array['name','quantity','price'] or jsonb_typeof(s->'name') is distinct from 'string' or char_length(btrim(s->>'name')) not between 2 and 120 or s->>'name' ~ '[[:cntrl:]]' or jsonb_typeof(s->'quantity') is distinct from 'number' or s->>'quantity' !~ '^[0-9]+$' or (s->>'quantity')::bigint not between 1 and 9999 or jsonb_typeof(s->'price') is distinct from 'number' or s->>'price' !~ '^[0-9]+$' or (s->>'price')::bigint not between 0 and 999999999 then return false;end if;
 if d->>'currency' in ('JPY','UGX','RWF') and (s->>'price')::bigint%100<>0 then return false;end if;
 t=t+(s->>'quantity')::bigint*(s->>'price')::bigint;
 end loop;return t<=999999999;
exception when others then return false;
end$$

create function quote_private.owner_write(p_business uuid,p_environment text,p_id uuid,p_version integer,p_action text,p_document jsonb,p_expiry date,p_enquiry uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare q public.business_quotes;b public.businesses;c text;z text;s jsonb;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then raise exception 'Quotes unavailable';end if;
 if p_action not in ('save','send') or p_action is null or p_id is null or p_version is null then raise exception 'Check quote details';end if;
 select * into q from public.business_quotes where id=p_id for update;
 if found then
 if q.business_id<>p_business or q.environment<>p_environment or q.version<>p_version or q.status<>'Draft' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 else
 if p_version<>0 or p_action<>'save' then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 end if;
 if p_action='save' then
 if not quote_private.valid(p_document) or p_expiry is null or p_expiry < (now() at time zone b.time_zone)::date or p_expiry > (now() at time zone b.time_zone)::date+366 then raise exception 'Check quote details and expiry';end if;
 select draft->>'currency' into c from public.business_service_catalogues where business_id=p_business and environment=p_environment;
 if p_document->>'currency'<>coalesce(c,'ZAR') then raise exception 'Business currency changed. Reload before saving.';end if;
 if p_enquiry is not null and not exists(select 1 from public.business_enquiries where id=p_enquiry and business_id=p_business and environment=p_environment) then raise exception 'Enquiry unavailable';end if;
 if q.id is null then insert into public.business_quotes(id,business_id,environment,enquiry_id,document,expires_on) values(p_id,p_business,p_environment,p_enquiry,p_document,p_expiry);
 else update public.business_quotes set document=p_document,expires_on=p_expiry,version=version+1 where id=p_id;end if;
 else
 if q.expires_on < (now() at time zone b.time_zone)::date then raise exception 'Update the expiry before sending.';end if;
 -- Capture explicit public business details only; no account metadata.
 select draft into s from public.business_profiles where business_id=p_business and environment=p_environment;
 s=jsonb_build_object('name',coalesce(nullif(s->>'name',''),b.name),'email',coalesce(s->>'email',''),'phone',coalesce(s->>'phone',''),'time_zone',b.time_zone);
 update public.business_quotes set status='Sent',sender=s,share_token=encode(extensions.gen_random_bytes(32),'hex'),sent_at=now(),version=version+1 where id=p_id;
 end if;
 return jsonb_build_object('id',p_id);
end$$

create function quote_private.customer(p_environment text,p_token text,p_response text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare q public.business_quotes;st text;
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' or not exists(select 1 from quote_private.ingress where environment=p_environment and enabled) then return '{}'::jsonb;end if;
 select * into q from public.business_quotes where share_token=p_token and environment=p_environment and status<>'Draft' for update;
 if not found then return '{}'::jsonb;end if;
 st=case when q.status='Sent' and q.expires_on < (now() at time zone (q.sender->>'time_zone'))::date then 'Expired' else q.status end;
 if p_response<>'' then
 if p_response is null or p_response not in ('Accepted','Declined') then raise exception 'Choose accept or decline';end if;
 if st='Sent' then update public.business_quotes set status=p_response,responded_at=now(),version=version+1 where id=q.id;st=p_response;
 elsif st<>p_response then raise exception 'Quote already answered or expired. Reload the page.';end if;
 end if;
 return jsonb_build_object('reference',upper(substr(q.id::text,1,8)),'document',q.document,'sender',q.sender,'expires_on',q.expires_on,'status',st,'sent_at',q.sent_at);
end$$

create function booking_private.instant(p_local timestamp,p_zone text) returns timestamptz language plpgsql stable set search_path='' as $$
declare t timestamptz;
begin
 if p_local is null or not exists(select 1 from pg_catalog.pg_timezone_names where name=p_zone) then raise exception 'Choose a valid date and time.';end if;
 t=p_local at time zone p_zone;
 if t at time zone p_zone <> p_local or exists(select 1 from generate_series(-180,180) m where m<>0 and (t+m*interval '1 minute') at time zone p_zone=p_local) then raise exception 'This local time is skipped or repeated by daylight saving. Choose another time.';end if;
 return t;
end$$

create function booking_private.owner_write(p_business uuid,p_environment text,p_id uuid,p_version integer,p_quote uuid,p_document jsonb,p_address text,p_local timestamp,p_zone text,p_duration integer,p_status text) returns jsonb language plpgsql security definer set search_path='' as $$
declare b public.businesses;r public.business_bookings;q public.business_quotes;c text;t timestamptz;d jsonb;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from booking_private.ingress where environment=p_environment and enabled) then raise exception 'Bookings unavailable.';end if;
 -- Serialize new requests per business, including retries from multiple browser tabs.
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,32));
 if p_id is null or p_version is null or p_version<0 then raise exception 'Check booking details.';end if;
 select * into r from public.business_bookings where id=p_id for update;
 if r.id is not null then
 if r.business_id<>p_business or r.environment<>p_environment or r.version<>p_version or r.quote_id is distinct from p_quote then raise exception 'Booking changed or unavailable. Reload before saving.';end if;
 if p_zone<>r.time_zone or p_zone is null then raise exception 'Booking time zone changed. Reload before saving.';end if;
 else
 if p_version<>0 then raise exception 'Booking changed or unavailable. Reload before saving.';end if;
 if p_zone is distinct from b.time_zone then raise exception 'Business time zone changed. Reload before saving.';end if;
 if p_status is distinct from 'Scheduled' then raise exception 'New bookings must be Scheduled.';end if;
 end if;
 d=p_document;
 if p_quote is not null then
 select * into q from public.business_quotes where id=p_quote and business_id=p_business and environment=p_environment and status='Accepted' for update;
 if not found then raise exception 'An accepted quote from this business is required.';end if;
 if r.id is null and exists(select 1 from public.business_bookings where quote_id=p_quote) then raise exception 'This quote already has a booking. Open it from the booking list.';end if;
 -- The accepted agreement is the source of truth; clients cannot change its price or customer.
 d=q.document;
 elsif r.id is null then
 select draft->>'currency' into c from public.business_service_catalogues where business_id=p_business and environment=p_environment;
 if d->>'currency' is distinct from coalesce(c,'ZAR') then raise exception 'Business currency changed. Reload before saving.';end if;
 elsif d->>'currency' is distinct from r.document->>'currency' then raise exception 'Booking currency cannot be changed.';
 end if;
 if not quote_private.valid(d) or p_address is null or char_length(btrim(p_address)) not between 5 and 1000 or p_address ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' or p_duration is null or p_duration not between 1 and 10080 or p_status is null or p_status not in ('Scheduled','In Progress','Completed','Cancelled') then raise exception 'Check booking details.';end if;
 t=booking_private.instant(p_local,p_zone);
 if p_local < timestamp '2000-01-01' or p_local >= timestamp '2100-01-01' then raise exception 'Choose a date between 2000 and 2099.';end if;
 if r.id is null then
 insert into public.business_bookings(id,business_id,environment,quote_id,document,address,starts_at,time_zone,duration_minutes) values(p_id,p_business,p_environment,p_quote,d,btrim(p_address),t,p_zone,p_duration);
 else
 update public.business_bookings set document=d,address=btrim(p_address),starts_at=t,duration_minutes=p_duration,status=p_status,version=version+1,updated_at=now() where id=p_id;
 end if;
 return jsonb_build_object('id',p_id);
end$$

create function customer_private.valid(d jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare k text;
begin
 if jsonb_typeof(d) is distinct from 'object' or (select count(*) from jsonb_object_keys(d))<>5 or not d ?& array['name','email','phone','address','notes'] then return false;end if;
 foreach k in array array['name','email','phone','address','notes'] loop
 if jsonb_typeof(d->k) is distinct from 'string' or d->>k ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then return false;end if;end loop;
 return char_length(btrim(d->>'name')) between 2 and 120 and char_length(d->>'email')<=254 and char_length(d->>'phone')<=40 and char_length(d->>'address')<=1000 and char_length(d->>'notes')<=2000
 and (d->>'email'<>'' or d->>'phone'<>'') and (d->>'email'='' or d->>'email' ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') and (d->>'phone'='' or (d->>'phone' ~ '^[+0-9 ()-]{5,40}$' and char_length(regexp_replace(d->>'phone','[^0-9]','','g'))>=5));
exception when others then return false;
end$$

create function customer_private.owner(p_business uuid,p_environment text) returns void language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) or not exists(select 1 from customer_private.ingress where environment=p_environment and enabled) then raise exception 'Customers unavailable.';end if;
end$$

create function customer_private.search(p_business uuid,p_environment text,p_search text,p_page integer) returns jsonb language plpgsql security definer set search_path='' as $$begin
 perform customer_private.owner(p_business,p_environment);
 if p_search is null or char_length(p_search)>120 or p_page is null or p_page not between 1 and 100000 then raise exception 'Check customer search.';end if;
 return coalesce((select jsonb_agg(to_jsonb(t)) from (select * from public.business_customers c where business_id=p_business and environment=p_environment and (p_search='' or strpos(lower(c.details->>'name'),lower(p_search))>0 or strpos(lower(c.details->>'email'),lower(p_search))>0 or (char_length(regexp_replace(p_search,'[^0-9]','','g'))>=3 and strpos(regexp_replace(c.details->>'phone','[^0-9]','','g'),regexp_replace(p_search,'[^0-9]','','g'))>0)) order by lower(details->>'name'),id limit 21 offset (p_page-1)*20)t),'[]'::jsonb);
end$$

create function customer_private.write(p_business uuid,p_environment text,p_id uuid,p_version integer,p_details jsonb,p_confirm boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.business_customers;matches jsonb;
begin
 perform customer_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,73));
 if p_id is null or p_version is null or p_version<0 or not customer_private.valid(p_details) then raise exception 'Check customer details.';end if;
 select * into r from public.business_customers where id=p_id for update;
 if (r.id is not null and (r.business_id<>p_business or r.environment<>p_environment or r.version<>p_version)) or (r.id is null and p_version<>0) then raise exception 'Customer changed or unavailable. Reload before saving.';end if;
 select jsonb_agg(jsonb_build_object('id',id,'name',details->>'name','email',details->>'email','phone',details->>'phone')) into matches from
 (select * from public.business_customers where business_id=p_business and environment=p_environment and id<>p_id and
 (lower(btrim(details->>'name'))=lower(btrim(p_details->>'name')) or (p_details->>'email'<>'' and lower(btrim(details->>'email'))=lower(btrim(p_details->>'email'))) or (p_details->>'phone'<>'' and regexp_replace(details->>'phone','[^0-9]','','g')=regexp_replace(p_details->>'phone','[^0-9]','','g'))) order by id limit 21)c;
 if matches is not null and not coalesce(p_confirm,false) then return jsonb_build_object('duplicates',matches);end if;
 if r.id is null then insert into public.business_customers(id,business_id,environment,details) values(p_id,p_business,p_environment,p_details);
 else update public.business_customers set details=p_details,version=version+1,updated_at=now() where id=p_id;end if;
 return jsonb_build_object('id',p_id);
end$$

create function customer_private.link(p_business uuid,p_environment text,p_customer uuid,p_kind text,p_record uuid,p_version integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare tbl text;changed uuid;
begin
 perform customer_private.owner(p_business,p_environment);
 if not exists(select 1 from public.business_customers where id=p_customer and business_id=p_business and environment=p_environment) then raise exception 'Customer unavailable.';end if;
 tbl=case p_kind when 'enquiry' then 'business_enquiries' when 'quote' then 'business_quotes' when 'booking' then 'business_bookings' else null end;
 if tbl is null then raise exception 'Record unavailable or already linked.';end if;
 execute format('update public.%I set customer_id=$1,version=version+1 where id=$2 and business_id=$3 and environment=$4 and version=$5 and customer_id is null returning id',tbl) into changed using p_customer,p_record,p_business,p_environment,p_version;
 if changed is null then raise exception 'Record unavailable or already linked.';end if;
 return jsonb_build_object('id',p_customer);
end$$

create function customer_private.quote_create(p_business uuid,p_environment text,p_id uuid,p_version integer,p_action text,p_document jsonb,p_expiry date,p_enquiry uuid,p_customer uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;cid uuid;
begin
 perform customer_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,73));
 if p_version is distinct from 0 or p_action is distinct from 'save' or exists(select 1 from public.business_quotes where id=p_id) then raise exception 'Quote changed or unavailable. Reload before saving.';end if;
 cid=p_customer;
 if p_enquiry is not null then select coalesce(cid,customer_id) into cid from public.business_enquiries where id=p_enquiry and business_id=p_business and environment=p_environment;end if;
 if cid is not null and not exists(select 1 from public.business_customers where id=cid and business_id=p_business and environment=p_environment) then raise exception 'Customer unavailable.';end if;
 result=quote_private.owner_write(p_business,p_environment,p_id,p_version,p_action,p_document,p_expiry,p_enquiry);
 update public.business_quotes set customer_id=cid where id=p_id;
 return result;
end$$

create function customer_private.booking_create(p_business uuid,p_environment text,p_id uuid,p_version integer,p_quote uuid,p_document jsonb,p_address text,p_local timestamp,p_zone text,p_duration integer,p_status text,p_customer uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;cid uuid;
begin
 perform customer_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,73));
 if p_version is distinct from 0 or exists(select 1 from public.business_bookings where id=p_id) then raise exception 'Booking changed or unavailable. Reload before saving.';end if;
 cid=p_customer;
 if p_quote is not null then
 select customer_id into cid from public.business_quotes where id=p_quote and business_id=p_business and environment=p_environment;
 if p_customer is not null and p_customer is distinct from cid then raise exception 'Customer unavailable.';end if;
 end if;
 if cid is not null and not exists(select 1 from public.business_customers where id=cid and business_id=p_business and environment=p_environment) then raise exception 'Customer unavailable.';end if;
 result=booking_private.owner_write(p_business,p_environment,p_id,p_version,p_quote,p_document,p_address,p_local,p_zone,p_duration,p_status);
 update public.business_bookings set customer_id=cid where id=p_id;
 return result;
end$$

create function staff_private.owner(p_business uuid,p_environment text) returns void language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) or not exists(select 1 from staff_private.ingress where environment=p_environment and enabled) then raise exception 'Staff unavailable.';end if;
end$$

create function staff_private.write(p_business uuid,p_environment text,p_id uuid,p_version integer,p_name text,p_email text,p_phone text,p_active boolean) returns jsonb language plpgsql security definer set search_path='' as $$
declare s public.business_staff;
begin
 perform staff_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,91));
 if p_id is null or p_version is null or p_version<0 or p_name is null or char_length(btrim(p_name)) not between 2 and 120 or p_name ~ '[\u0001-\u001f\u007f]' or p_email is null or char_length(p_email)>254 or (p_email<>'' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or p_phone is null or (p_phone<>'' and (p_phone !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(p_phone,'[^0-9]','','g'))<5)) or p_active is null then raise exception 'Check staff details.';end if;
 select * into s from public.business_staff where id=p_id for update;
 if (s.id is not null and (s.business_id<>p_business or s.environment<>p_environment or s.version<>p_version)) or (s.id is null and p_version<>0) then raise exception 'Staff changed or unavailable. Reload before saving.';end if;
 if s.id is null then insert into public.business_staff(id,business_id,environment,name,email,phone,active) values(p_id,p_business,p_environment,btrim(p_name),btrim(p_email),btrim(p_phone),p_active);
 else update public.business_staff set name=btrim(p_name),email=btrim(p_email),phone=btrim(p_phone),active=p_active,version=version+1,updated_at=now() where id=p_id;end if;
 return jsonb_build_object('id',p_id);
end$$

create function staff_private.assign(p_business uuid,p_environment text,p_booking uuid,p_version integer,p_staff jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare b public.business_bookings;ids uuid[];
begin
 perform staff_private.owner(p_business,p_environment);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_business::text,91));
 select * into b from public.business_bookings where id=p_booking and business_id=p_business and environment=p_environment for update;
 if not found or p_version is distinct from b.assignment_version then raise exception 'Assignments changed or unavailable. Reload before saving.';end if;
 if jsonb_typeof(p_staff) is distinct from 'array' or jsonb_array_length(p_staff)>100 then raise exception 'Choose up to 100 staff members.';end if;
 if exists(select 1 from jsonb_array_elements(p_staff) x where jsonb_typeof(x)<>'string' or x#>>'{}' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$') then raise exception 'Choose valid staff members.';end if;
 select coalesce(array_agg(distinct x::uuid),'{}'::uuid[]) into ids from jsonb_array_elements_text(p_staff) x;
 if exists(select 1 from unnest(ids) i where not exists(select 1 from public.business_staff s where s.id=i and s.business_id=p_business and s.environment=p_environment and (s.active or exists(select 1 from public.business_booking_staff a where a.booking_id=p_booking and a.staff_id=s.id)))) then raise exception 'Choose active staff from this business. Existing inactive assignments may be retained.';end if;
 delete from public.business_booking_staff where booking_id=p_booking and not(staff_id=any(ids));
 insert into public.business_booking_staff(booking_id,staff_id,business_id,environment) select p_booking,i,p_business,p_environment from unnest(ids)i on conflict do nothing;
 update public.business_bookings set assignment_version=assignment_version+1 where id=p_booking;
 return jsonb_build_object('id',p_booking);
end$$

create function invoice_private.write(p_business uuid,p_environment text,p_id uuid,p_version integer,p_action text,p_document jsonb default null,p_due date default null,p_booking uuid default null,p_reason text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare b public.businesses;i public.business_invoices;r public.business_bookings;d jsonb;c text;s jsonb;n bigint;existing uuid;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from invoice_private.ingress where environment=p_environment and enabled) then raise exception 'Invoices unavailable';end if;
 if p_id is null or p_version is null or p_action is null or p_action not in ('save','issue','void') then raise exception 'Check invoice details';end if;
 if p_reason is null or char_length(p_reason)>500 or p_reason ~ '[[:cntrl:]]' then raise exception 'Check correction reason';end if;
 -- Serializes numbering, creation and payment-affecting transitions within this tenant.
 perform pg_advisory_xact_lock(hashtextextended(p_business::text||':invoice:'||p_environment,0));
 select * into i from public.business_invoices where id=p_id for update;
 if found then
 if i.business_id<>p_business or i.environment<>p_environment then raise exception 'Invoice unavailable';end if;
 if i.version<>p_version then raise exception 'Invoice changed. Reload before saving.';end if;
 elsif p_action<>'save' or p_version<>0 then raise exception 'Invoice changed or unavailable';end if;
 if p_action='save' then
 if i.id is not null and i.state<>'Draft' then raise exception 'Issued invoices cannot be edited';end if;
 if p_due is null or p_due<date '2000-01-01' or p_due>date '2099-12-31' then raise exception 'Choose a valid due date';end if;
 if i.id is not null then p_booking=i.booking_id;end if;
 d=p_document;
 if p_booking is not null then
 select * into r from public.business_bookings where id=p_booking and business_id=p_business and environment=p_environment for share;
 if not found or (i.id is null and r.status='Cancelled') then raise exception 'Booking unavailable or cancelled';end if;
 if i.id is null then
 select id into existing from public.business_invoices where booking_id=p_booking and business_id=p_business and environment=p_environment;
 if found then return jsonb_build_object('id',existing);end if;
 end if;
 -- First creation snapshots the saved agreement. Later draft edits cannot change it.
 d=case when i.id is null then r.document else i.document end;
 elsif i.id is null then
 select draft->>'currency' into c from public.business_service_catalogues where business_id=p_business and environment=p_environment;
 if d->>'currency' is distinct from coalesce(c,'ZAR') then raise exception 'Business currency changed. Reload.';end if;
 elsif d->>'currency' is distinct from i.document->>'currency' then raise exception 'Invoice currency cannot be changed';end if;
 if not quote_private.valid(d) or invoice_private.total(d)<1 then raise exception 'Add valid items with a positive total';end if;
 if i.id is null then insert into public.business_invoices(id,business_id,environment,booking_id,document,due_on) values(p_id,p_business,p_environment,p_booking,d,p_due);
 else update public.business_invoices set document=d,due_on=p_due,version=version+1 where id=p_id;end if;
 elsif p_action='issue' then
 if i.state<>'Draft' then raise exception 'Invoice already issued or void';end if;
 if i.due_on < (now() at time zone b.time_zone)::date then raise exception 'Update the due date before issuing';end if;
 insert into invoice_private.counters values(p_business,p_environment,1) on conflict(business_id,environment) do update set value=invoice_private.counters.value+1 returning value into n;
 select draft into s from public.business_profiles where business_id=p_business and environment=p_environment;
 s=jsonb_build_object('name',coalesce(nullif(s->>'name',''),b.name),'email',coalesce(s->>'email',''),'phone',coalesce(s->>'phone',''),'time_zone',b.time_zone);
 update public.business_invoices set state='Issued',number='INV-'||lpad(n::text,greatest(6,length(n::text)),'0'),sender=s,share_token=encode(extensions.gen_random_bytes(32),'hex'),issued_at=now(),version=version+1 where id=p_id;
 else
 if i.state<>'Issued' then raise exception 'Only issued invoices can be voided';end if;
 if exists(select 1 from public.business_invoice_payments where invoice_id=p_id group by invoice_id having sum(case when reversal_of is null then amount else -amount end)<>0) then raise exception 'Reverse recorded payments before voiding. A reversal does not refund money.';end if;
 if p_reason is null or char_length(btrim(p_reason)) not between 5 and 500 or p_reason ~ '[[:cntrl:]]' then raise exception 'Enter a correction reason from 5 to 500 characters';end if;
 update public.business_invoices set state='Void',void_reason=btrim(p_reason),voided_at=now(),version=version+1 where id=p_id;
 end if;
 insert into public.business_invoice_events(invoice_id,business_id,environment,action,actor,detail) values(p_id,p_business,p_environment,p_action,auth.uid(),jsonb_build_object('reason',p_reason,'version',p_version));
 return jsonb_build_object('id',p_id);
end$$

create function invoice_private.payment(p_business uuid,p_environment text,p_invoice uuid,p_id uuid,p_amount bigint,p_paid_on date,p_reference text,p_reversal uuid default null,p_reason text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare b public.businesses;i public.business_invoices;p public.business_invoice_payments;old public.business_invoice_payments;paid bigint;
begin
 select * into b from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or not exists(select 1 from invoice_private.ingress where environment=p_environment and enabled) then raise exception 'Payments unavailable';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_business::text||':invoice:'||p_environment,0));
 select * into i from public.business_invoices where id=p_invoice and business_id=p_business and environment=p_environment for update;
 if not found then raise exception 'Invoice unavailable';end if;
 select * into old from public.business_invoice_payments where id=p_id;
 if found then
 if old.invoice_id=p_invoice and old.business_id=p_business and old.environment=p_environment and old.reversal_of is not distinct from p_reversal and old.amount=p_amount and old.paid_on=p_paid_on and old.reference=btrim(p_reference) and old.reason=btrim(p_reason) then return jsonb_build_object('id',p_id);end if;
 raise exception 'Payment submission changed. Reload before saving.';end if;
 if i.state<>'Issued' then raise exception 'Payments require an issued invoice';end if;
 if p_id is null or p_amount is null or p_amount not between 1 and 999999999 or p_paid_on is null or p_paid_on<date '2000-01-01' or p_paid_on>(now() at time zone b.time_zone)::date or p_reference is null or char_length(btrim(p_reference)) not between 2 and 120 or p_reference ~ '[[:cntrl:]]' then raise exception 'Check amount, payment date and reference';end if;
 if i.document->>'currency' in ('JPY','UGX','RWF') and p_amount%100<>0 then raise exception 'Use whole currency amounts';end if;
 if p_reversal is not null then
 select * into p from public.business_invoice_payments where id=p_reversal and invoice_id=p_invoice and business_id=p_business and environment=p_environment and reversal_of is null;
 if not found or exists(select 1 from public.business_invoice_payments where reversal_of=p_reversal) or p.amount<>p_amount or p.paid_on<>p_paid_on or p.reference<>btrim(p_reference) or p_reason is null or char_length(btrim(p_reason)) not between 5 and 500 or p_reason ~ '[[:cntrl:]]' then raise exception 'Payment already reversed or correction invalid';end if;
 else
 if p_reason is distinct from '' then raise exception 'Correction reason only applies to reversals';end if;
 -- Same invoice, reference, date and amount is a duplicate even with a new submission key.
 if exists(select 1 from public.business_invoice_payments x where x.invoice_id=p_invoice and x.reversal_of is null and x.amount=p_amount and x.paid_on=p_paid_on and lower(x.reference)=lower(btrim(p_reference)) and not exists(select 1 from public.business_invoice_payments y where y.reversal_of=x.id)) then raise exception 'This payment is already recorded';end if;
 select coalesce(sum(case when reversal_of is null then amount else -amount end),0) into paid from public.business_invoice_payments where invoice_id=p_invoice;
 if p_amount>invoice_private.total(i.document)-paid then raise exception 'Payment exceeds the outstanding balance';end if;
 end if;
 insert into public.business_invoice_payments(id,invoice_id,business_id,environment,amount,paid_on,reference,created_by,reversal_of,reason) values(p_id,p_invoice,p_business,p_environment,p_amount,p_paid_on,btrim(p_reference),auth.uid(),p_reversal,btrim(p_reason));
 update public.business_invoices set version=version+1 where id=p_invoice;
 insert into public.business_invoice_events(invoice_id,business_id,environment,action,actor,detail) values(p_invoice,p_business,p_environment,case when p_reversal is null then 'payment' else 'reversal' end,auth.uid(),jsonb_build_object('payment',p_id,'reversal_of',p_reversal,'reason',p_reason));
 return jsonb_build_object('id',p_id);
end$$

create function invoice_private.customer(p_environment text,p_token text) returns jsonb language plpgsql security definer set search_path='' as $$
declare i public.business_invoices;paid bigint;
begin
 if p_token is null or p_token !~ '^[a-f0-9]{64}$' or not exists(select 1 from invoice_private.ingress where environment=p_environment and enabled) then return '{}'::jsonb;end if;
 select * into i from public.business_invoices where environment=p_environment and share_token=p_token and state<>'Draft';
 if not found then return '{}'::jsonb;end if;
 select coalesce(sum(case when reversal_of is null then amount else -amount end),0) into paid from public.business_invoice_payments where invoice_id=i.id;
 return jsonb_build_object('number',i.number,'document',i.document-'email'-'phone','sender',i.sender,'due_on',i.due_on,'issued_at',i.issued_at,'total',invoice_private.total(i.document),'paid',paid,'balance',invoice_private.total(i.document)-paid,'status',case when i.state='Void' then 'Void' when paid=invoice_private.total(i.document) then 'Paid' when paid>0 then 'Part Paid' else 'Unpaid' end);
end$$

create function public.business_dashboard(p_business uuid,p_environment text,p_month date default null) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare z text; today date; first_day date; next_day date; result jsonb;
begin
 select time_zone into z from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true);
 if not found or p_environment is null or p_environment not in ('live','preview') then raise exception 'Dashboard unavailable';end if;
 today=(now() at time zone z)::date;
 first_day=date_trunc('month',coalesce(p_month,today))::date;
 if first_day<date '2000-01-01' or first_day>date '2099-12-01' then raise exception 'Choose a valid month';end if;
 next_day=(first_day+interval '1 month')::date;
 with bookings as materialized (
 select s.id,s.starts_at,s.duration_minutes,s.status,s.document->>'name' as name,s.assigned_staff
 from public.business_booking_schedule s where s.business_id=p_business and s.environment=p_environment and s.status<>'Cancelled'
 and s.starts_at < ((today+1)::timestamp at time zone z)
 and s.starts_at + s.duration_minutes*interval '1 minute' > (today::timestamp at time zone z)
 ), invoices as materialized (
 select i.id,i.number,i.document->>'name' as name,i.document->>'currency' as currency,i.status,i.due_on,i.balance
 from public.business_invoice_list i where i.business_id=p_business and i.environment=p_environment and i.state='Issued' and i.balance>0
 ), money as (
 select currency,0::bigint receipts,0::bigint reversals,0::bigint outstanding,0::bigint overdue
 from (select coalesce((select draft->>'currency' from public.business_service_catalogues where business_id=p_business and environment=p_environment),'ZAR') currency) c
 union all select currency,0,0,balance,case when due_on<today then balance else 0 end from invoices
 union all
 select i.document->>'currency',case when p.reversal_of is null then p.amount else 0 end,case when p.reversal_of is not null then p.amount else 0 end,0,0
 from public.business_invoice_payments p join public.business_invoices i on i.id=p.invoice_id and i.business_id=p.business_id and i.environment=p.environment
 where p.business_id=p_business and p.environment=p_environment and p.paid_on>=first_day and p.paid_on<next_day
 ), totals as (select currency,sum(receipts) receipts,sum(reversals) reversals,sum(receipts)-sum(reversals) net,sum(outstanding) outstanding,sum(overdue) overdue from money group by currency)
 select jsonb_build_object(
 'as_of',now(),'today',today,'zone',z,'month',first_day,'month_end',next_day-1,
 'bookings_count',(select count(*) from bookings),
 'bookings',coalesce((select jsonb_agg(to_jsonb(t) order by starts_at,id) from (select * from bookings order by starts_at,id limit 8) t),'[]'::jsonb),
 'new_enquiries',(select count(*) from public.business_enquiries where business_id=p_business and environment=p_environment and status='New'),
 'awaiting_quotes',(select count(*) from public.business_quotes where business_id=p_business and environment=p_environment and status='Sent' and expires_on>=today),
 'unpaid',(select count(*) from invoices where status='Unpaid'),
 'part_paid',(select count(*) from invoices where status='Part Paid'),
 'overdue_count',(select count(*) from invoices where due_on<today),
 'invoices',coalesce((select jsonb_agg(to_jsonb(t) order by due_on,id) from (select * from invoices order by due_on,id limit 5) t),'[]'::jsonb),
 'money',(select jsonb_agg(to_jsonb(t) order by currency) from totals t)
 ) into result;
 return result;
end$$

create function enquiry_private.manual_create(p_business uuid,p_environment text,p_id uuid,p_name text,p_email text,p_phone text,p_requirements text) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 if p_environment is distinct from 'preview' then raise exception 'Manual enquiries are preview only';end if;
 if not exists(select 1 from public.businesses where id=p_business and owner_id=auth.uid() and not coalesce((auth.jwt()->>'is_anonymous')::boolean,true)) then raise exception 'Enquiry unavailable';end if;
 if p_id is null or p_name is null or p_email is null or p_phone is null or p_requirements is null or char_length(btrim(p_name)) not between 2 and 120 or char_length(p_email)>254 or char_length(p_phone)>40 or char_length(btrim(p_requirements)) not between 10 and 4000 or (p_email='' and p_phone='') or (p_email<>'' and p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') or (p_phone<>'' and (p_phone !~ '^[+0-9 ()-]{5,40}$' or char_length(regexp_replace(p_phone,'[^0-9]','','g'))<5)) or p_name||p_email||p_phone ~ '[[:cntrl:]]' or p_requirements ~ '[\u0001-\u0008\u000b\u000c\u000e-\u001f\u007f]' then raise exception 'Check enquiry details';end if;
 insert into public.business_enquiries(id,business_id,environment,request_id,page_slug,customer_name,email,phone,requirements)
 values(p_id,p_business,p_environment,p_id,'',btrim(p_name),p_email,p_phone,btrim(p_requirements)) on conflict(id) do nothing;
 if not exists(select 1 from public.business_enquiries where id=p_id and business_id=p_business and environment=p_environment and customer_name=btrim(p_name) and email=p_email and phone=p_phone and requirements=btrim(p_requirements)) then raise exception 'Enquiry submission changed';end if;
 return jsonb_build_object('id',p_id);
end$$

